WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (673::BIGINT, 'En general el curso fue muy sencillo, la clases eran algo largas, pero es lo normal en cursos de verano. El profesor explica bien los contenidos, depende de usted si quiere aprender. Los trabajos eran cortos y sencillos de realizar.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Pocos exámenes']::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'e522c7fac85e0be173747d92c0fad450a9c665988fef39501cfebb361b660960'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'El curso fue prácticamente todo asincrónico. Solo algunas presentaciones presenciales. El profe tiene mucha experiencia en negocios de TI, pero su prioridad no es el TEC. Todo es grupal, exámenes virtuales asincrónicos. Para pasar está bien, para aprender no.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2024-11-14T00:00:00+00:00'::TIMESTAMPTZ, '572117e929a7043acc89941b3b1bc6463b35a368b1feda5a669e5f76a2939457'::TEXT, ARRAY[2529]::BIGINT[]),
    (673::BIGINT, 'En general es buen profe, pero deja demasiado de lado el curso en sus obligaciones, no contesta mensajes ni correos. Las clases son cortas, y manda varias veces clase asincrónica, si el curso dice semipresencial, probablemente nunca tenga una clase presencial en el semestre.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '23d408e350d833f8e61d96556012081faee29be3332e163950df1794fb35ea72'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Es buen profe y sabe mucho, pero también deja de lado las clases y decide hacerlas asincrónicas, los exámenes son relativamente fáciles pero aveces le gusta desquitarse. Hay que hacer todos los trabajos y estudiar para los exámenes y se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1f8c5740042e198c7d33dca50ae180ba3c686646d5d8cb18d5e2153e381c3ea5'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Este mae sabe mucho de calidad, PERO la prioridad de él no es ser profe tiene otras cosas y eso lo hace que deje el TEC aún ladito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, 'c0b2d015ce40065e25517c6f3b577e9ad3a9bc43fd4d0c528d4d6cba45ea81d5'::TEXT, ARRAY[2540]::BIGINT[]),
    (673::BIGINT, 'Mejoró mucho este semestre :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-02-17T00:00:00+00:00'::TIMESTAMPTZ, '28b6141334b263d59c9037ecb21de6f63683e15483aa936373f6dc5e12a3e318'::TEXT, ARRAY[2540]::BIGINT[]),
    (673::BIGINT, 'Buen profe, explica bastante bien solo que le falta organizar con la asistente :D Llevaría otro curso con él.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'b846ca7e4a3c19e6f7f21291cf7e90867d7cf39420cbea044666886444a1cc45'::TEXT, ARRAY[2540]::BIGINT[]),
    (673::BIGINT, 'Es el 3er curso que llevo con él y este sin dudas ha sido el PEOR. Desorganización a más no poder, nunca sabe nada, califica hasta el final y baja puntos por todo. Nunca responde rápido. PÉSIMO'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'a84ea538acf84c09364b8bd3794008e80387eaa0637e0b93f07ffb9b14d09eff'::TEXT, ARRAY[2540]::BIGINT[]),
    (673::BIGINT, '¿Conoce un profe malo?, pues este le gana.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'd7e2d3448330446de4763d2d04341def5e8208a5bc66cb163cbe5b7d2ec2bd19'::TEXT, ARRAY[2540]::BIGINT[]),
    (673::BIGINT, 'PÉSIMO que asco legalmente nunca supe que hacía en ese curso.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '434851ab65749402830737ddc59fb8e70e64129c4298f5b69e478c2c148a847f'::TEXT, ARRAY[2530]::BIGINT[]),
    (673::BIGINT, 'Facil puede ser el peor profesor de todos. Solo lee diapositivas, es vago entonces deja clases asincronicas con temas todos X. Y las evaluaciones no son claras. Evitelo a toda costa.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5ac0683abaf2d049d7c5e0cb13d48a89318bc3e48d8e5d07aeb47eed85fc3447'::TEXT, ARRAY[2530]::BIGINT[]),
    (673::BIGINT, 'Este mae ni sabe dónde está parado, daba clases asincrónicas a cada rato para no bretear y cuando asignaba evaluaciones las instrucciones eran poco claras. La asistente es otra qué pasa detrás del palo, usted le pregunta algo ella nunca sabe nada.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '45d31bba14dd068b18ad677413e79dee6b5035645af305913f82a5f9b56062d0'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'El curso es muy autodidacta. Pone asignaciones asincrónicas (MUY extensas) de semana de por medio y dan poco tiempo para la entrega. Usa metodologías rarísimas para estos trabajos extraclase y sobretodo para las exposiciones. La asistente fatal, no responde y revisa todo hasta el final. Muy malo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-15T00:00:00+00:00'::TIMESTAMPTZ, '001575df63d1d40b27b0f6f9ecd6b81cb96d1489a26831f0f82a94ad2554dcfa'::TEXT, ARRAY[3576]::BIGINT[]),
    (673::BIGINT, 'Manda a investigar temas diferentes y solo exponen 2 grs. Otro día nos manda a investigar el mismo tema y 1m antes avisa que quiere que todos expongan algo distinto a los otros grps. Todo un GENIO... y así es Viceministro. La asist. No sabe ni donde está. Se codea con Pedro para ser el peor profe.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-15T00:00:00+00:00'::TIMESTAMPTZ, '787c9c62f7dcbae760fcd478e18df9c20920da4fcce7195593a8ba98ad25403a'::TEXT, ARRAY[2530]::BIGINT[]),
    (673::BIGINT, 'Es un buen profe, solo que hay que ser bastante autodidacta. Eso si, no revisa ninguna nota hasta el puro final del semestre, casi la ultima semana. Entonces hay que adivinar cuales son los errores que se cometen. El tema es muy interesante, talvez es la metodología que es ineficiente.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec1a5658ef4b77d7844ff34b995ab8d3797e72125dab7848e260a10788b47b9b'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Para llevar el curso es necesario ser bastante autodidacta. Las clases son una semana asincrónica y la otra sincrónica y cuando son sincrónicas son aproximadamente de dos horas entonces toca explicar muchos temas en poco tiempo. Les recomiendo conseguir el libro del curso desde el principio.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'f9deaf9f98784b9a74efae64f629c399a686bc6b62be1dd8248a1fb58f4b08c4'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Este mae hace cambios de evaluación impresionantes, elimino un examen, todos los quices, agrego mas tareas, los % subieron exagerado, las clases PÉSIMAS, NO ENSEÑA NADA, deja mucho que desear, es la competencia de Segreda....'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-10T00:00:00+00:00'::TIMESTAMPTZ, '5f347aeac7198ecab190f4c13851f2db14d5e5d1b76e6aacd27910005083fb60'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'PÉSIMO! da una clase de una hora cada 15 días donde lo que hace es LEER diapositivas. La siguiente semana deja pura práctica que ni idea como hacerla porque el Mae no explica. Retroalimentación NUNCA. Adivine que falló en las tareas para hacerlo bien en el examen.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '02ace4ad50d699cd8e7a73c32a6f2f1876c128e0be78ed978c5beaf3e0c6f96f'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Sinceramente explica muy poco la materia, le falta abordar los temas más a fondo. Sin embargo, no considero que sea malo explicando, sino que explica muy rápido y la metodología no es la mejor (clases asincrónicas). Las clases asincrónicas son demasiado largas y con instrucciones poco claras.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '0f43756c84c24769e690b91242209853233618c4f908373c88528f7b3c72d70f'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, '(Virtual) La verdad, el curso virtual es difícil. El profe da la mitad de las clases sincrónicas (sólo explica teoría, nada de práctica), y la otra mitad asincrónicas (trabajos muy largos). Dura hasta final de semestre para revisar los trabajos, ud nunca va a tener retroalimentación.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '390d20ba697b0f9ba2436512f717de2a1693a7569b202e53be2bd8c7ce8c73af'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, '(Virtual) La mitad de las clases son sincrónicas y la otra mitad asincrónicas. Llega a explicar teoría y los trabajos son prácticos y sumamente laaargos. Lo bueno: las clases no son de 4 horas, las hace más cortas. Lo malo: es un curso autodidacta. PD: El profe es buena nota.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, '370c9edffe8b05e7c5c354f024f701dfa6cc16c522faa9f83f0317daf83376ed'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Da una clase de una hora cada 15 días Entre la semana que no da clase, deja un trabajo que ni tiene que ver con la clase semanal'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'da488abd6c9fb6655fe52572fd6d6640b96f158505aa78b503371469dc253f08'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Explica muy bien, aunque el curso fue muy teórico. Deja muchas tareas y trabajos, la mayoría se puede hacer en grupos. Las clases son muy largas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '438d7adbd2147f6a71138cecabc132973b32526f29e2b532e2cf68992d1b7636'::TEXT, ARRAY[2530]::BIGINT[]),
    (673::BIGINT, 'El profe explica muy bien. Cada semana se hacen tareas, pero son pequeñas y se pueden hacer en grupos. Lo feo es la hora del curso, siempre lo dan de noche.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd72b1b171d0cc55f95aaab07607d6fd4d2bfaa9e4a3993433575f5c7432b237f'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'El profe es super bueno, aunque los examenes son un toque difíciles y no se podrían realizar si no dejara llevar compu, ademas se tiene que poner atención sino pierdes el curso'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, '8450bdcde5da4d5748590c2e5551bfb10fa5cac044c7e77b656f8b4dcca0ccbc'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'El profesor es un crack, las clases a veces se tornan aburridas pero siempre se aprende un montón'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-13T00:00:00+00:00'::TIMESTAMPTZ, '1e0c42cd92ad8f14a4cd970c2c6dada0320b30a2ece58eace85ce7e056a2b596'::TEXT, ARRAY[2524]::BIGINT[]),
    (673::BIGINT, 'Es muy bueno en la materia, un poco dificil, pero explica muy bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-10T00:00:00+00:00'::TIMESTAMPTZ, '857bdaca2057a0357197621981ec5259fa70d3eb83a30c40dee9ea4a0213d0bc'::TEXT, ARRAY[2524]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
